class Solution:
    def basicCalculatorIV(self, expression, evalvars, evalints):
        env = dict(zip(evalvars, evalints))
        tokens = expression.replace('(', ' ( ').replace(')', ' ) ').split()
        self.i = 0
        def mul(a, b):
            r = {}
            for k1, v1 in a.items():
                for k2, v2 in b.items():
                    k = tuple(sorted(k1 + k2))
                    r[k] = r.get(k, 0) + v1 * v2
            return r
        def factor():
            t = tokens[self.i]
            self.i += 1
            if t == '(':
                p = expr()
                self.i += 1
                return p
            if t.isdigit():
                return {(): int(t)}
            if t in env:
                return {(): env[t]}
            return {(t,): 1}
        def term():
            p = factor()
            while self.i < len(tokens) and tokens[self.i] == '*':
                self.i += 1
                p = mul(p, factor())
            return p
        def expr():
            p, sign = {}, 1
            while True:
                if self.i < len(tokens) and tokens[self.i] in '+-':
                    sign = -1 if tokens[self.i] == '-' else 1
                    self.i += 1
                for k, v in term().items():
                    p[k] = p.get(k, 0) + v * sign
                if self.i >= len(tokens) or tokens[self.i] == ')':
                    break
            return p
        p = expr()
        res = []
        for k in sorted(p.keys(), key=lambda x: (-len(x), x)):
            if p[k]:
                s = str(p[k])
                for v in k:
                    s += '*' + v
                res.append(s)
        return res

