            auto k = k1; k.insert(k.end(), k2.begin(), k2.end());
            sort(k.begin(), k.end()); r[k] += v1 * v2;
        }
        return r;
    }
    Poly expr() {
        Poly p; int sign = 1;
        while (true) {
            if (i < (int)tk.size() && (tk[i] == "+" || tk[i] == "-")) { sign = tk[i] == "-" ? -1 : 1; i++; }
            for (auto& [k, v] : term()) p[k] += v * sign;
            if (i >= (int)tk.size() || tk[i] == ")") break;
        }
        return p;
    }
    Poly term() {
        Poly p = factor();
        while (i < (int)tk.size() && tk[i] == "*") { i++; p = mul(p, factor()); }
        return p;
    }
    Poly factor() {
        string t = tk[i++];
        if (t == "(") { Poly p = expr(); i++; return p; }
        Poly p;
        if (isdigit(t[0])) p[{}] = stoi(t);
