    Map<List<String>,Integer> mul(Map<List<String>,Integer> a, Map<List<String>,Integer> b) {
        Map<List<String>,Integer> r = new HashMap<>();
        for (var e1 : a.entrySet()) for (var e2 : b.entrySet()) {
            List<String> k = new ArrayList<>(e1.getKey()); k.addAll(e2.getKey());
            Collections.sort(k);
            r.merge(k, e1.getValue() * e2.getValue(), Integer::sum);
        }
        return r;
    }
    Map<List<String>,Integer> expr() {
        Map<List<String>,Integer> p = new HashMap<>(); int sign = 1;
        while (true) {
            if (i < tk.length && (tk[i].equals("+") || tk[i].equals("-"))) { sign = tk[i].equals("-") ? -1 : 1; i++; }
            for (var e : term().entrySet()) p.merge(e.getKey(), e.getValue() * sign, Integer::sum);
            if (i >= tk.length || tk[i].equals(")")) break;
        }
        return p;
    }
    Map<List<String>,Integer> term() {
        var p = factor();
        while (i < tk.length && tk[i].equals("*")) { i++; p = mul(p, factor()); }
        return p;
    }
    Map<List<String>,Integer> factor() {
        String t = tk[i++];
        if (t.equals("(")) { var p = expr(); i++; return p; }
        Map<List<String>,Integer> p = new HashMap<>();
        if (Character.isDigit(t.charAt(0))) p.put(new ArrayList<>(), Integer.parseInt(t));
        else if (env.containsKey(t)) p.put(new ArrayList<>(), env.get(t));
        else p.put(List.of(t), 1);
        return p;
    }
    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        env = new HashMap<>();
        for (int j = 0; j < evalvars.length; j++) env.put(evalvars[j], evalints[j]);
        List<String> list = new ArrayList<>(); StringBuilder cur = new StringBuilder();
        for (char c : expression.toCharArray()) {
            if (c == ' ') { if (cur.length() > 0) { list.add(cur.toString()); cur.setLength(0); } }
            else if (c == '(' || c == ')') { if (cur.length() > 0) { list.add(cur.toString()); cur.setLength(0); } list.add(String.valueOf(c)); }
            else cur.append(c);
        }
        if (cur.length() > 0) list.add(cur.toString());
        tk = list.toArray(new String[0]);
        var p = expr();
        List<List<String>> keys = new ArrayList<>(p.keySet());
        keys.sort((a, b) -> a.size() != b.size() ? b.size() - a.size() : a.compareTo(b));
        List<String> res = new ArrayList<>();
        for (var k : keys) {
            int c = p.get(k);
            if (c == 0) continue;
            StringBuilder sb = new StringBuilder(String.valueOf(c));
            for (var w : k) sb.append("*").append(w);
            res.add(sb.toString());
        }
