class Solution {
    Map<List<String>,Integer> mul(Map<List<String>,Integer> a, Map<List<String>,Integer> b) {
        Map<List<String>,Integer> r = new HashMap<>();
        for (var e1 : a.entrySet()) for (var e2 : b.entrySet()) {
            List<String> k = new ArrayList<>(e1.getKey()); k.addAll(e2.getKey());
            Collections.sort(k);
            r.merge(k, e1.getValue() * e2.getValue(), Integer::sum);
        }
        return r;
    }
    Map<List<String>,Integer> add(Map<List<String>,Integer> a, Map<List<String>,Integer> b, int s) {
        Map<List<String>,Integer> r = new HashMap<>(a);
        for (var e : b.entrySet()) r.merge(e.getKey(), e.getValue() * s, Integer::sum);
        return r;
    }
    int prec(char o) { return o == '*' ? 2 : 1; }
    void apply(Deque<Map<List<String>,Integer>> st, Deque<Character> op) {
        var b = st.pop(); var a = st.pop(); char o = op.pop();
        st.push(o == '*' ? mul(a, b) : add(a, b, o == '-' ? -1 : 1));
    }
    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        Map<String,Integer> env = new HashMap<>();
        for (int j = 0; j < evalvars.length; j++) env.put(evalvars[j], evalints[j]);
        List<String> tk = new ArrayList<>(); StringBuilder cur = new StringBuilder();
        for (char c : expression.toCharArray()) {
            if (c == ' ') { if (cur.length() > 0) { tk.add(cur.toString()); cur.setLength(0); } }
            else if (c == '(' || c == ')') { if (cur.length() > 0) { tk.add(cur.toString()); cur.setLength(0); } tk.add(String.valueOf(c)); }
            else cur.append(c);
        }
        if (cur.length() > 0) tk.add(cur.toString());
        Deque<Map<List<String>,Integer>> st = new ArrayDeque<>();
        Deque<Character> op = new ArrayDeque<>();
        for (String t : tk) {
            if (t.equals("(")) op.push('(');
            else if (t.equals(")")) { while (op.peek() != '(') apply(st, op); op.pop(); }
            else if (t.equals("+") || t.equals("-") || t.equals("*")) {
                while (!op.isEmpty() && op.peek() != '(' && prec(op.peek()) >= prec(t.charAt(0))) apply(st, op);
                op.push(t.charAt(0));
            } else {
                Map<List<String>,Integer> p = new HashMap<>();
                if (Character.isDigit(t.charAt(0))) p.put(new ArrayList<>(), Integer.parseInt(t));
                else if (env.containsKey(t)) p.put(new ArrayList<>(), env.get(t));
                else p.put(List.of(t), 1);
                st.push(p);
            }
        }
        while (!op.isEmpty()) apply(st, op);
        var p = st.pop();
        List<List<String>> keys = new ArrayList<>(p.keySet());
        keys.sort((a, b) -> a.size() != b.size() ? b.size() - a.size() : a.compareTo(b));
        List<String> res = new ArrayList<>();
